import struct, zlib
def chunk(t, d): return struct.pack(">I", len(d)) + t + d + struct.pack(">I", zlib.crc32(t + d) & 0xffffffff)
def paeth(a, b, c):
    p = a + b - c; pa, pb, pc = abs(p - a), abs(p - b), abs(p - c)
    return a if pa <= pb and pa <= pc else (b if pb <= pc else c)
def png(name, w, h, depth, ctype, rows, bpp, plte=b""):
    out, prev = bytearray(), bytearray(len(rows[0]))
    for y, line in enumerate(rows):
        k = y % 5
        enc = bytearray(len(line))
        for i in range(len(line)):
            a = line[i - bpp] if i >= bpp else 0; b = prev[i]; c = prev[i - bpp] if i >= bpp else 0
            enc[i] = (line[i] - [0, a, b, (a + b) // 2, paeth(a, b, c)][k]) & 0xFF
        out += bytes([k]) + enc; prev = line
    data = b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, depth, ctype, 0, 0, 0))
    if plte: data += chunk(b"PLTE", plte)
    open(name, "wb").write(data + chunk(b"IDAT", zlib.compress(bytes(out))) + chunk(b"IEND", b""))
def band(x, y, h):
    return (100, 160, 255) if y < h // 3 else ((100, 200, 50) if y < 2 * h // 3 else (160 + (x % 7) * 9, 130, 60))
w, h = 24, 15
png("filtered.png", w, h, 8, 2, [bytearray(b"".join(bytes(band(x, y, h)) for x in range(w))) for y in range(h)], 3)

